import numpy as np
z=np.load('source_pixels.npz')['rgb'].astype(float)
# Track a moving object using local template of f0 patch with color normalized? Search each frame around previous position.
def track(t0,box,frames,search=4):
 x0,y0,x1,y1=box; tpl=z[t0,y0:y1,x0:x1]; pos=(x0,y0); out=[]
 for i in frames:
  a=z[i]; best=None
  for dy in range(-search,search+1):
   for dx in range(-search,search+1):
    X0=pos[0]+dx;Y0=pos[1]+dy;X1=X0+(x1-x0);Y1=Y0+(y1-y0)
    if X0<0 or Y0<0 or X1>256 or Y1>144:continue
    d=np.abs(a[Y0:Y1,X0:X1]-tpl).mean()
    if best is None or d<best[0]:best=(d,dx,dy)
  pos=(pos[0]+best[1],pos[1]+best[2]);out.append((i,pos,best))
 return out
print('red initial')
for x in track(0,(160,52,176,67),range(1,20),6):print(x)
