import numpy as np
z=np.load('source_pixels.npz')['rgb'].astype(float)
# track candidate object 0 patch on red region and candidate object 1 patch on yellow region, centered from f0
# use normalized cross-correlation manually to find large displacement from f0 and f48
def corr(a,b):
 a=a-a.mean((0,1));b=b-b.mean((0,1)); den=np.sqrt((a*a).sum()*(b*b).sum()); return (a*b).sum()/den if den else 0
def search(t0,box,target,rad=80):
 x0,y0,x1,y1=box; tpl=z[t0,y0:y1,x0:x1]; a=z[target];best=None
 for dy in range(-rad,rad+1):
  for dx in range(-rad,rad+1):
   X0=x0+dx;Y0=y0+dy
   if X0<0 or Y0<0 or X0+(x1-x0)>256 or Y0+(y1-y0)>144: continue
   v=corr(a[Y0:Y0+(y1-y0),X0:X0+(x1-x0)],tpl)
   if best is None or v>best[0]:best=(v,dx,dy)
 return best
for box in [(160,52,176,67),(125,58,155,80),(95,75,125,95),(60,88,80,102)]:
 print('box',box)
 for t in [0,8,16,24,32,48,64,95]:print(t,search(0,box,t,100))
